def page(title,body,path='/',description='The personal headquarters of Emod Vafa. Growth leadership, independent ventures, and systems built for long-term value.',extra_schema=None):
 ld='<script type="application/ld+json">'+json.dumps(person)+'</script><script type="application/ld+json">'+json.dumps({"@context":"https://schema.org","@graph":ORGS})+'</script>'
 if extra_schema: ld+='<script type="application/ld+json">'+json.dumps(extra_schema)+'</script>'
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><meta name="description" content="'+html.escape(description)+'"><link rel="canonical" href="https://vafa.co'+path+'"><meta property="og:title" content="'+html.escape(title)+'"><meta property="og:description" content="'+html.escape(description)+'"><meta property="og:type" content="website"><meta property="og:url" content="https://vafa.co'+path+'"><meta name="theme-color" content="#f4f1e9"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css">'+ld+'</head><body><a class="skip" href="#main">Skip to content</a><header class="wrap">'+nav+'</header><main id="main">'+body+'</main><footer class="wrap"><a class="wordmark" href="/">VAFA<span> / </span>CO</a><p>The personal headquarters of Emod Vafa.</p><div><a href="/identity.json">Public identity</a><a href="/privacy/">Privacy</a><a href="/about/">About</a><a href="/talent/">Talent</a><a href="/real-estate/">Luxury Real Estate Marketing</a><a href="/case-studies/intercap/">Intercap case study</a><a href="/case-studies/verticalscope/">VerticalScope case study</a><a href="/case-studies/mirian/">Mirian case study</a><span>© 2026 Emod Vafa</span></div></footer></body></html>'
def write(path,title,body,description=None,extra_schema=None):
 dest=OUT/path/'index.html'; dest.parent.mkdir(parents=True,exist_ok=True); dest.write_text(page(title,body,'/'+str(path).strip('/')+'/',description,extra_schema) if description else page(title,body,'/'+str(path).strip('/')+'/',extra_schema=extra_schema))
def article_schema(headline,path):
 return {"@context":"https://schema.org","@type":"Article","headline":headline,"author":{"@type":"Person","name":"Emod Vafa","url":"https://vafa.co/"},"datePublished":"2026-11-27","mainEntityOfPage":"https://vafa.co"+path}
