for v in ventures:
 write(Path('ventures')/v['slug'],v['name']+' — Emod Vafa',venture_body(v),v.get('positioning',v['text']))

def experience_card(e,i):
 name=html.escape(e['name']); category=html.escape(e['industry']); kind=html.escape(e['kind'])
 return '<article class="brand-card" data-industry="'+category+'" data-kind="'+kind+'"><div class="brand-face'+(' logo-dark' if e.get('logo_dark') else '')+'"><span class="brand-number">'+('0' if i<10 else '')+str(i)+'</span><h2>'+('<img class="brand-logo" src="'+html.escape(e['logo'])+'" alt="'+name+'" loading="lazy" width="260" height="90">' if e.get('logo') else name)+'</h2><span class="brand-category">'+category+'</span></div><div class="brand-body"><p class="eyebrow">'+kind+'</p><p class="brand-role">'+html.escape(e['relationship'])+'</p><p class="business-blurb">'+html.escape(e.get('business',e['industry']))+'</p><details><summary>About this experience <span aria-hidden="true">+</span></summary><p>'+html.escape(e['text'])+'</p>'+('<a class="engagement-link" href="mailto:Emod@Vafa.co?subject='+__import__('urllib.parse',fromlist=['quote']).quote('Experience: '+e['name'])+'">Discuss my work with this business ↗</a>' if e['kind']=='Professional experience' else '')+('<a class="text-link" href="'+e['case_study']+'">Read the case study ↗</a>' if e.get('case_study') else '')+('<a class="text-link" href="'+e['url']+'">Venture profile ↗</a>' if 'url' in e else '')+'</details></div></article>'
def tier_grid(entries,start):
 return '<div class="brand-grid">'+''.join(experience_card(e,start+i) for i,e in enumerate(entries))+'</div>'
def experience_page():
 entries=[dict(e,kind=e.get('kind', 'Career' if e['name'].startswith('Intercap') else 'Client work')) for e in experience if e.get('status') != 'draft']
 entries += [dict(name=v['name'], relationship=v['role']+' · '+v['status'],industry='Finance' if v['slug']=='canada-business-loan' else 'Technology',text=v['detail'],kind='Ventures',url='/ventures/'+v['slug']+'/') for v in ventures]
 featured=[e for e in entries if e.get('featured')]
 full_list=[e for e in entries if e.get('tier')=='full-list']
 rest=[e for e in entries if not e.get('featured') and e.get('tier')!='full-list']
 career=[e for e in rest if e['kind'] in ('Career','Agency account','Dealer account','VerticalScope property')]
 client=[e for e in rest if e['kind'] in ('Client','Client engagement','Client work','Project work','Campaign work')]
 venture_tier=[e for e in rest if e['kind']=='Ventures']
 assert len(featured)+len(career)+len(client)+len(venture_tier)+len(full_list)==len(entries), 'tier partition lost entries: %s vs %s' % (len(featured)+len(career)+len(client)+len(venture_tier)+len(full_list), len(entries))
 n=1
 sections='<h3 class="tier-heading">Featured</h3>'+tier_grid(featured,n); n+=len(featured)
 sections+='<h3 class="tier-heading">Career &amp; agency</h3>'+tier_grid(career,n); n+=len(career)
 sections+='<h3 class="tier-heading">Client &amp; partner work</h3>'+tier_grid(client,n); n+=len(client)
 sections+='<h3 class="tier-heading">Ventures</h3>'+tier_grid(venture_tier,n); n+=len(venture_tier)
 sections+='<details class="full-list" id="full-list"><summary>View full list <span aria-hidden="true">+</span></summary>'+tier_grid(full_list,n)+'</details>'
 filters=''.join('<button type="button" data-filter="'+c+'" aria-pressed="'+('true' if c=='All' else 'false')+'">'+c+'</button>' for c in ['All','Legal','Automotive','Real Estate','Technology','Marketing','Finance','Commerce','Home Services'])
 return '<section class="wrap experience-intro"><p class="eyebrow">Selected experience / Emod Vafa</p><h1>The businesses behind<br><em>the work.</em></h1><div class="experience-deck"><p>More than 15 years across industries. A consistent focus on customer acquisition, digital growth, and building revenue systems.</p><span>Leadership. Client work.<br>Independent ventures.</span></div></section><section class="wrap brand-collection" aria-labelledby="collection-title"><div class="collection-heading"><h2 id="collection-title">Selected businesses & teams</h2><p id="result-count" role="status" aria-live="polite">'+str(len(entries))+' selected profiles</p></div><div class="collection-tools"><label for="brand-search">Find a business or brand<input id="brand-search" type="search" placeholder="Search by name or industry" autocomplete="off"></label><button type="button" id="print-experience">Print / Save PDF ↗</button></div><div class="brand-filters" role="group" aria-label="Filter experience by industry">'+filters+'</div>'+sections+'<p class="editorial-note">Real estate work in detail: <a href="/real-estate/">Luxury Real Estate Marketing ↗</a></p><p class="editorial-note">Case studies: <a href="/case-studies/intercap/">Intercap ↗</a> · <a href="/case-studies/verticalscope/">VerticalScope ↗</a> · <a href="/case-studies/mirian/">Mirian Law Firm ↗</a></p><p class="editorial-note">More: <a href="/about/">About Emod ↗</a> · <a href="/talent/">Talent &amp; skills ↗</a></p><p id="empty-state" class="empty-state" hidden>Additional experience in this industry is being documented. <a href="mailto:Emod@Vafa.co?subject=Experience%20enquiry">Contact Emod for relevant background ↗</a></p><p class="editorial-note">Experience spans career roles, agency work, client engagements, and ventures. A listed brand does not imply direct employment, ownership, or endorsement. Specific relationships are stated where documented.</p></section><section class="experience-cta"><div class="wrap"><p class="eyebrow">The next chapter</p><h2>Experience is a starting point.<br><em>What matters is what comes next.</em></h2><a class="text-link" href="https://cal.com/emodvafa">Discuss a leadership role or collaboration ↗</a></div></section><script src="/experience.js" defer></script>'
write(Path('experience'),'Selected Experience — Emod Vafa',experience_page())
real_estate_body='''<section class="wrap detail"><a class="eyebrow" href="/experience/">← Selected experience</a><p class="eyebrow">Real Estate · Toronto &amp; International</p><h1>Luxury Real Estate<br><em>Marketing.</em></h1><p class="lead">Growth marketing for pre-construction and international developments, from a licensed real estate broker. Project pages, high-intent paid search, landing pages, and broker handoff — built to turn project interest into conversations.</p><div class="detail-grid"><div><h2>What I do</h2><ul><li><strong>Project positioning.</strong> How a development is presented to its buyers, before any campaign runs.</li><li><strong>High-intent paid search.</strong> Google Search for buyers already looking for the project or the area.</li><li><strong>Paid social.</strong> Meta awareness and retargeting to build and re-engage the audience.</li><li><strong>Project landing pages.</strong> One page per project, built around the development and its buyers.</li><li><strong>Lead forms.</strong> Inquiry capture on the landing page.</li><li><strong>WhatsApp capture.</strong> Follow-up where buyers already talk.</li><li><strong>Broker handoff.</strong> Leads routed to broker partners for follow-up.</li></ul></div><dl><dt>My role</dt><dd>Licensed Real Estate Broker · Growth marketer</dd><dt>Focus</dt><dd>Toronto pre-construction · Dubai developments</dd><dt>Based</dt><dd>Toronto, Canada · Working globally</dd></dl></div><div class="detail-grid"><div><h2>Selected experience</h2><h3>Toronto pre-construction project pages</h3><p>Produced and managed project-specific pages for Toronto pre-construction developments through aCondo.ca, supporting project discovery and buyer inquiries. 39 condo and townhome project pages completed between October 16 and December 6, 2018.</p><h3>Buyer inquiry routing</h3><p>Supported project-specific inquiry capture and routed buyer leads to broker partners for follow-up, 2019 to 2021.</p><h3>Sobha Dubai campaign</h3><p>Campaign planning and paid search execution for Sobha Siniya Island and Sobha Central in 2025: Google Search and Display, Meta awareness and retargeting, project-specific landing pages, forms, WhatsApp follow-up, targeting Australia, London, and India.</p></div></div><div class="detail-grid"><div><h2>How the system works</h2><p>This is the system I build for a development. It describes the approach, not outcomes already achieved.</p><ol><li><strong>Development and buyer research.</strong> Understand the project and who it is for.</li><li><strong>Market and audience selection.</strong> Choose where to run and who to reach.</li><li><strong>Project landing page and campaign.</strong> One page per project, with campaigns built around it.</li><li><strong>Lead capture and qualification workflow.</strong> Forms and WhatsApp, with a workflow to sort inquiries.</li><li><strong>Broker follow-up.</strong> Leads handed to broker partners.</li><li><strong>Measurement.</strong> Inquiries, qualified buyers, viewings, reservations, and sales tracked, so the system can be improved.</li></ol></div></div><p class="editorial-note">Scope note: this page describes documented project and campaign work. It is not a claim of units sold, viewings booked, or a broad record of international luxury sales.</p></section><section class="contact"><div class="wrap"><p class="eyebrow">Connect</p><h2>Talk about a development<br><em>or a campaign.</em></h2><p>For pre-construction and international project marketing.</p><a class="email" href="mailto:Emod@Vafa.co">Emod@Vafa.co <span aria-hidden="true">↗</span></a><div class="contact-links"><a href="https://cal.com/emodvafa">Book a conversation ↗</a><a href="https://ca.linkedin.com/in/emodvafa">LinkedIn ↗</a><a href="tel:+14164004699">416 400 4699</a></div></div></section>'''
write(Path('real-estate'),'Luxury Real Estate Marketing — Emod Vafa',real_estate_body,'Growth marketing for pre-construction and international real estate developments, from licensed broker Emod Vafa. Project pages, paid search, landing pages, and broker handoff.')
intercap_body='''<section class="wrap detail"><a class="eyebrow" href="/experience/">← Selected experience</a><p class="eyebrow">Case study · Intercap · Jan 2023 – Mar 2025</p><h1>Building an in-house marketing team <em>from scratch.</em></h1><p class="lead">Director of Marketing at Intercap, a Canadian venture capital firm, January 2023 to March 2025. I built the in-house marketing function that supported a selection of Intercap's portfolio companies, including the go-to-market for .inc and .box.</p><div class="detail-grid"><div><h2>The outcome</h2><ul><li><strong>Team:</strong> from 1 to 10+ specialists.</li><li><strong>ARR supported:</strong> from $5M to $10M.</li><li><strong>Lead volume:</strong> up 50%.</li><li><strong>Cost per lead:</strong> from about $180 to about $70 (approximate, Emod-provided).</li><li><strong>Monthly budget:</strong> $250K.</li></ul><p>These are outcomes of the portfolio marketing system, built alongside product, sales, and the portfolio companies. ARR is portfolio revenue the system supported, not revenue one person closed alone.</p></div><dl><dt>My role</dt><dd>Director of Marketing</dd><dt>Company</dt><dd>Intercap Inc., Toronto</dd><dt>Dates</dt><dd>Jan 2023 – Mar 2025</dd><dt>Scope</dt><dd>Portfolio marketing · .inc and .box go-to-market</dd></dl></div><div class="detail-grid"><div><h2>Situation</h2><p>Intercap is a Canadian venture capital firm. Its portfolio includes premium domains and digital products, including .inc and .box. When I joined, there was no in-house marketing function. The work had to be built, not inherited.</p><h2>Mandate</h2><p>Build one marketing system that could serve more than one business at once: paid acquisition, lifecycle nurture, and go-to-market, with reporting that connected spend to revenue.</p></div></div><div class="detail-grid"><div><h2>The system built</h2><ul><li><strong>Team.</strong> From one person to 10+ specialists across paid media, email, social, SEO, content, analytics, automation, and web development, with a set reporting cadence.</li><li><strong>Paid acquisition.</strong> Google Ads, Meta, and LinkedIn, tuned by bid optimization, audience refinement, campaign structure, and funnel fixes.</li><li><strong>Lifecycle and CRM.</strong> Lead nurture and segmentation, with Close CRM pipeline workflows and Twilio SMS carrying leads toward sales.</li><li><strong>Outbound.</strong> More than 1M emails a month through Mailgun and SendGrid.</li><li><strong>Measurement.</strong> Reporting built around the customer journey: UTM systems, Microsoft Clarity, and Mixpanel, so spend could be traced to outcomes.</li><li><strong>AI-assisted operations.</strong> AI-assisted workflows raised campaign and reporting output without adding equivalent headcount.</li></ul></div></div><div class="detail-grid"><div><h2>Go-to-market: .inc and .box</h2><p>Partnered with product and revenue on go-to-market for .inc and .box. Positioning and pre-launch demand produced thousands of interested prospects before launch.</p><h2>Measurable outcome</h2><p>ARR supported grew from $5M to $10M while the system was in place. Lead volume rose 50%. Cost per lead fell from about $180 to about $70. The team grew from 1 to 10+ specialists on a $250K monthly budget.</p><h2>Lessons</h2><ul><li><strong>Specialization beats headcount.</strong> A lean team where each person owns a lane scales further than a larger generalist team.</li><li><strong>Attribution is the system.</strong> UTMs, Clarity, and Mixpanel turned marketing from activity into evidence.</li><li><strong>Build the capability, not the campaign.</strong> The same system served multiple portfolio businesses, which is why it kept paying off.</li></ul></div></div><div class="detail-grid"><div><h2>Listen: the story in Emod's words</h2><p>Biz Builder Spotlight, April 14, 2025, 37 minutes. Emod describes building the in-house team from scratch, running lean teams with deep specialization, tracking the customer journey with UTMs, Clarity, and Mixpanel, and future-proofing marketing operations.</p><a class="text-link" href="https://creators.spotify.com/pod/profile/jonathansherman/episodes/How-Emod-Vafa-Built-a-Scalable-In-House-Marketing-Team-for-a-Venture-Capital-Firms-Portfolio-Companies-e31hnv6">Listen on Spotify ↗</a></div></div><p class="editorial-note">Attribution note: ARR and lead volume are outcomes of the portfolio marketing system Emod built with product, sales, and the portfolio companies. Cost per lead is approximate, from Emod's own account: about $180 down to about $70.</p></section><section class="contact"><div class="wrap"><p class="eyebrow">Connect</p><h2>Talk about building<br><em>a growth system.</em></h2><p>For leadership roles, portfolio marketing, and go-to-market work.</p><a class="email" href="mailto:Emod@Vafa.co">Emod@Vafa.co <span aria-hidden="true">↗</span></a><div class="contact-links"><a href="https://cal.com/emodvafa">Book a conversation ↗</a><a href="https://ca.linkedin.com/in/emodvafa">LinkedIn ↗</a><a href="tel:+14164004699">416 400 4699</a></div></div></section>'''
write(Path('case-studies')/'intercap','Building Intercap\u2019s In-House Marketing Team — Emod Vafa',intercap_body,'How Emod Vafa built Intercap\u2019s in-house marketing team from 1 to 10+ specialists, supporting ARR growth from $5M to $10M and go-to-market for .inc and .box.',article_schema('Building Intercap\u2019s In-House Marketing Team','/case-studies/intercap/'))
verticalscope_body='''<section class="wrap detail"><a class="eyebrow" href="/experience/">← Selected experience</a><p class="eyebrow">Case study · VerticalScope · 2018–2022</p><h1>Affiliate growth,<br><em>held to the line.</em></h1><p class="lead">Senior Growth Marketing Manager at VerticalScope, Toronto, 2018 to 2022. Affiliate marketing, programmatic, ecommerce, and automotive media across five high-traffic consumer properties: RateMDs, AutoGuide, RedFlagDeals, FitRated, and TreadmillReviews.net.</p><div class="detail-grid"><div><h2>The outcome</h2><ul><li><strong>Affiliate revenue:</strong> up 75%.</li><li><strong>CPC:</strong> down 45%.</li><li><strong>Black Friday program:</strong> about $1.5M, scaled only while the roughly 3:1 revenue-to-spend line held.</li><li><strong>Properties:</strong> five high-traffic consumer properties.</li></ul></div><dl><dt>My role</dt><dd>Senior Growth Marketing Manager</dd><dt>Company</dt><dd>VerticalScope Inc., Toronto</dd><dt>Dates</dt><dd>2018 – 2022</dd><dt>Scope</dt><dd>Paid search · Display · Native · Programmatic</dd></dl></div><div class="detail-grid"><div><h2>Context</h2><p>Five high-traffic consumer properties, each with its own audience and revenue mix. My mandate was growth across paid search, display, native, and programmatic — and I owned pacing, retargeting, and what got killed.</p><h2>Challenge</h2><p>Growth had to come from buying better, not buying more. On high-volume properties, traffic costs move fast. The discipline was holding the revenue line while scaling spend.</p></div></div><div class="detail-grid"><div><h2>What I did</h2><ul><li><strong>Algorithmic bidding and audience optimization</strong> to cut CPC 45% while affiliate revenue grew 75%.</li><li><strong>Programmatic traffic arbitrage.</strong> Bought lower-cost display and native through DSPs and converted it on fitness, health, and automotive audiences.</li><li><strong>Owned the kill decisions.</strong> Pacing, retargeting, and what got cut were mine to decide, and cutting early protected the line.</li><li><strong>Black Friday, held to 3:1.</strong> Led a program of about $1.5M, scaling only while the roughly 3:1 revenue-to-spend line held.</li></ul></div></div><div class="detail-grid"><div><h2>Result</h2><p>Affiliate revenue up 75% and CPC down 45% across the five properties. The Black Friday program ran at about $1.5M without breaking the 3:1 line.</p><h2>What it taught me</h2><ul><li><strong>The line is the strategy.</strong> A ratio held under pressure is worth more than a bigger budget.</li><li><strong>Arbitrage is a skill.</strong> Buy attention where it is cheap, convert it where intent is real.</li><li><strong>Kill decisions are as valuable as launches.</strong> What you stop funding is what keeps the program honest.</li></ul></div></div><p class="editorial-note">Attribution note: revenue and CPC figures are from the VerticalScope program as reported in Emod's own career record, 2018–2022.</p></section><section class="contact"><div class="wrap"><p class="eyebrow">Connect</p><h2>Talk about growth<br><em>that holds its line.</em></h2><p>For affiliate, programmatic, and performance marketing work.</p><a class="email" href="mailto:Emod@Vafa.co">Emod@Vafa.co <span aria-hidden="true">↗</span></a><div class="contact-links"><a href="https://cal.com/emodvafa">Discuss a similar challenge ↗</a><a href="https://ca.linkedin.com/in/emodvafa">LinkedIn ↗</a><a href="tel:+14164004699">416 400 4699</a></div></div></section>'''
write(Path('case-studies')/'verticalscope','Affiliate Growth at VerticalScope — Emod Vafa',verticalscope_body,'How Emod Vafa grew affiliate revenue 75% and cut CPC 45% at VerticalScope, and ran a $1.5M Black Friday program held to a 3:1 revenue line.',article_schema('Affiliate Growth at VerticalScope','/case-studies/verticalscope/'))
mirian_body='''<section class="wrap detail"><a class="eyebrow" href="/experience/">← Selected experience</a><p class="eyebrow">Case study · Mirian Law Firm · 2023, returning 2026</p><h1>Expensive clicks,<br><em>honest answers.</em></h1><p class="lead">Ross Mirian's personal-injury firm in Thornhill. Google Ads and YouTube, July to October 2023. Ross returned in November 2026 for a PPC audit and a YouTube campaign.</p><div class="detail-grid"><div><h2>The outcome</h2><ul><li><strong>Traffic:</strong> 4,800+ users a month at a $0.89 CPC (October 2023 report).</li><li><strong>Mobile:</strong> 88% of users, from Toronto, Brampton, and Mississauga.</li><li><strong>The honest result:</strong> inquiries arrived, but the injuries were not severe enough to become cases. Ads paused November 1, 2023.</li><li><strong>The return:</strong> Ross came back in November 2026 for a PPC audit and a YouTube campaign.</li></ul></div><dl><dt>My role</dt><dd>Paid search &amp; YouTube</dd><dt>Client</dt><dd>Mirian Law Firm, Thornhill</dd><dt>Dates</dt><dd>Jul – Oct 2023, returning Nov 2026</dd><dt>Scope</dt><dd>Google Ads · YouTube · PPC audit</dd></dl></div><div class="detail-grid"><div><h2>Context</h2><p>Personal-injury search is among the most expensive auctions in Canada. At agency level, Emod managed PI accounts at $50 to $200+ CPC. Mirian needed traffic that could become cases, not just clicks.</p><h2>Challenge</h2><p>Cheap traffic is easy. Traffic that survives intake is hard. The campaign had to find people with serious injuries in the GTA — and be honest about what it found.</p></div></div><div class="detail-grid"><div><h2>What I did</h2><ul><li><strong>Google Ads, July to October 2023.</strong> Core keywords to the homepage with UTM tracking, and a plan to split into geo campaigns for Oshawa, Pickering, and other GTA markets.</li><li><strong>Mobile landing pages</strong> built for the campaign, and YouTube work alongside search.</li><li><strong>Reported what the traffic actually did.</strong> The October 2023 report showed 4,800+ users a month at $0.89 CPC — and that the inquiries were not severe enough to become cases.</li><li><strong>Paused.</strong> Ads went on hold November 1, 2023, rather than keep spending on traffic that did not clear the bar.</li></ul></div></div><div class="detail-grid"><div><h2>Result</h2><p>Volume at a low cost: 4,800+ users a month at $0.89 CPC, 88% mobile. But volume was not the result. The result was that the traffic did not produce cases the firm could take — and the honest move was to pause.</p><h2>What it taught me</h2><ul><li><strong>A low CPC is not a result.</strong> In personal injury, the result is a case the firm can take.</li><li><strong>Pausing is a decision, not a failure.</strong> Stopping spend on the wrong traffic protects the client and the relationship.</li><li><strong>Returning clients are the real metric.</strong> Ross came back in November 2026 for a PPC audit and a YouTube campaign — first for the Farsi-speaking GTA community, then for the general GTA population. The firm is multilingual: Farsi, Dari, Arabic, Cantonese, and Mandarin.</li></ul></div></div><p class="editorial-note">Attribution note: traffic figures are from the October 2023 report. No cases signed, viewings, or revenue are claimed. The 2026 return is a PPC audit and YouTube campaign, as requested by the client in November 2026.</p></section><section class="contact"><div class="wrap"><p class="eyebrow">Connect</p><h2>Talk about acquisition<br><em>that survives intake.</em></h2><p>For legal marketing and high-intent paid search.</p><a class="email" href="mailto:Emod@Vafa.co">Emod@Vafa.co <span aria-hidden="true">↗</span></a><div class="contact-links"><a href="https://cal.com/emodvafa">Discuss a similar challenge ↗</a><a href="https://ca.linkedin.com/in/emodvafa">LinkedIn ↗</a><a href="tel:+14164004699">416 400 4699</a></div></div></section>'''
write(Path('case-studies')/'mirian','Mirian Law Firm: Personal-Injury Paid Search — Emod Vafa',mirian_body,'Personal-injury paid search for Mirian Law Firm: 4,800+ users a month at $0.89 CPC in 2023, an honest pause, and a return in 2026.',article_schema('Mirian Law Firm: Personal-Injury Paid Search','/case-studies/mirian/'))
talent_body='''<section class="wrap detail"><a class="eyebrow" href="/experience/">← Selected experience</a><p class="eyebrow">Talent &amp; skills</p><h1>What I<br><em>can do.</em></h1><p class="lead">Fifteen years across paid search, growth leadership, and venture building. The capabilities, the tools, and the languages behind the work.</p><div class="detail-grid"><div><h2>Professional capabilities</h2><ul><li><strong>Paid search and performance.</strong> Google Ads, Meta, YouTube.</li><li><strong>Affiliate and programmatic growth.</strong> DSPs, algorithmic bidding, traffic arbitrage.</li><li><strong>Conversion optimization.</strong> Landing pages, A/B testing, funnel fixes.</li><li><strong>Lead generation and qualification.</strong> Capture, routing, and CRM workflows.</li><li><strong>Marketing automation.</strong> HubSpot, Salesforce, Close CRM, Mailgun, SendGrid, Twilio.</li><li><strong>AI-assisted analysis and workflow.</strong> OpenAI, Claude, Gemini, and workflow automation.</li><li><strong>Client reporting systems.</strong> GA4, Mixpanel, Microsoft Clarity, dashboards.</li><li><strong>Executive leadership.</strong> Marketing teams from 1 to 10+ specialists.</li></ul></div><dl><dt>Languages</dt><dd>English · Persian (Farsi)</dd><dt>Education</dt><dd>Honours BBA, Marketing — Schulich School of Business, York University, 2011</dd><dt>Based</dt><dd>Toronto, Canada · Working globally</dd></dl></div><div class="detail-grid"><div><h2>Beyond business</h2><p>Outside business, I practise Sama — Sufi whirling — and play the Persian daf. I serve on the board of Dance Ontario and work for Persian and Middle Eastern culture in Canada: performance, teaching, and community. It is the other half of the same discipline: attention, repetition, and movement with intent.</p></div></div></section><section class="contact"><div class="wrap"><p class="eyebrow">Connect</p><h2>Put the capabilities<br><em>to work.</em></h2><p>For leadership roles, client work, and collaborations.</p><a class="email" href="mailto:Emod@Vafa.co">Emod@Vafa.co <span aria-hidden="true">↗</span></a><div class="contact-links"><a href="https://cal.com/emodvafa">Book a conversation ↗</a><a href="https://ca.linkedin.com/in/emodvafa">LinkedIn ↗</a><a href="tel:+14164004699">416 400 4699</a></div></div></section>'''
write(Path('talent'),'Talent & Skills — Emod Vafa',talent_body,'The capabilities, tools, and languages behind Emod Vafa\u2019s work: paid search, affiliate and programmatic growth, conversion, automation, AI-assisted workflows, and team leadership.')
about_body='''<section class="wrap detail"><a class="eyebrow" href="/">← Home</a><p class="eyebrow">About</p><h1>About<br><em>Emod.</em></h1><p class="lead">Growth executive, entrepreneur, builder. The thinking behind the work, in four parts.</p><div class="detail-grid"><div><h2>How I think</h2><p>Growth is a discipline. Systems beat tactics. I measure what compounds: the cost of a lead, the quality of the pipeline, the revenue the system supports. A campaign is a test. A system is the asset.</p></div></div><div class="detail-grid"><div><h2>What I build</h2><p>Revenue systems, intelligent operations, and enduring digital assets. The work connects demand generation, conversion, and retention around the economics of the business — then uses technology and automation to make good work repeatable.</p></div></div><div class="detail-grid"><div><h2>Where I have worked</h2><p>More than 15 years across technology, legal services, automotive, real estate, and commerce. From hands-on paid search to director-level leadership. From agency portfolios of 70+ accounts to building an in-house marketing team from one person to ten.</p></div></div><div class="detail-grid"><div><h2>Why it matters</h2><p>The point is long-term value: businesses that endure, systems that keep working, and work that compounds. That is what I build toward.</p></div></div></section><section class="contact"><div class="wrap"><p class="eyebrow">Connect</p><h2>Start a<br><em>conversation.</em></h2><p>For leadership opportunities, business growth, and thoughtful collaborations.</p><a class="email" href="mailto:Emod@Vafa.co">Emod@Vafa.co <span aria-hidden="true">↗</span></a><div class="contact-links"><a href="https://cal.com/emodvafa">Book a conversation ↗</a><a href="https://ca.linkedin.com/in/emodvafa">LinkedIn ↗</a><a href="tel:+14164004699">416 400 4699</a></div></div></section>'''
write(Path('about'),'About Emod Vafa',about_body,'How Emod Vafa thinks about growth, what he builds, where he has worked, and why it matters.')
write(Path('privacy'),'Privacy — Vafa.co','<section class="wrap detail"><p class="eyebrow">Privacy · October 16, 2026</p><h1>A straightforward<br><em>approach to privacy.</em></h1><p>This site does not include advertising trackers, analytics scripts, cookies set by application code, or a contact database. The hosting provider may process technical request information to operate and secure the site.</p><p>Email and scheduling links open third-party services, which apply their own privacy policies. Information you choose to send by email is used to respond to your enquiry.</p><p>Questions: <a href="mailto:Emod@Vafa.co">Emod@Vafa.co</a>.</p></section>')
